using System.Diagnostics;
using System.Globalization;
using System.IO.Pipes;
using System.Security.Principal;
using System.Threading.Channels;
using Microsoft.Extensions.Logging;
using WinNetworkManager.Telemetry.Collection;
using WinNetworkManager.Telemetry.Model;

namespace WinNetworkManager.Telemetry.Ipc;

/// <summary>Command-line options of the elevated helper.</summary>
/// <param name="PipeName">Pipe name generated by the UI.</param>
/// <param name="ParentPid">PID of the UI process; the only accepted client, and the helper exits with it.</param>
/// <param name="ClientUserSid">SID of the user running the UI (granted access to the pipe).</param>
public sealed record CollectorHostOptions(string PipeName, int ParentPid, string ClientUserSid)
{
    /// <summary>Parses <c>--pipe NAME --parent PID --client-sid SID</c>. Returns null on any invalid input.</summary>
    public static CollectorHostOptions? Parse(IReadOnlyList<string> args)
    {
        ArgumentNullException.ThrowIfNull(args);
        string? pipe = null;
        string? sid = null;
        int parent = 0;
        for (int i = 0; i + 1 < args.Count; i += 2)
        {
            switch (args[i])
            {
                case "--pipe":
                    pipe = args[i + 1];
                    break;
                case "--parent":
                    if (!int.TryParse(args[i + 1], NumberStyles.None, CultureInfo.InvariantCulture, out parent))
                    {
                        return null;
                    }

                    break;
                case "--client-sid":
                    sid = args[i + 1];
                    break;
                default:
                    return null;
            }
        }

        if (pipe is null || sid is null || parent <= 0 || !PipeIdentity.IsValidPipeName(pipe))
        {
            return null;
        }

        try
        {
            _ = new SecurityIdentifier(sid);
        }
        catch (ArgumentException)
        {
            return null;
        }

        return new CollectorHostOptions(pipe, parent, sid);
    }

    /// <summary>Formats the arguments for <see cref="Parse"/>.</summary>
    public IReadOnlyList<string> ToArguments() =>
        ["--pipe", PipeName, "--parent", ParentPid.ToString(CultureInfo.InvariantCulture), "--client-sid", ClientUserSid];
}

/// <summary>Exit codes of the helper.</summary>
public static class CollectorExitCodes
{
    /// <summary>Normal exit.</summary>
    public const int Success = 0;

    /// <summary>Invalid arguments.</summary>
    public const int InvalidArguments = 2;

    /// <summary>The parent process does not exist.</summary>
    public const int ParentNotFound = 3;

    /// <summary>No client connected in time.</summary>
    public const int ConnectTimeout = 4;

    /// <summary>A process other than the parent connected.</summary>
    public const int UnexpectedClient = 5;

    /// <summary>The collector could not start (e.g. access denied).</summary>
    public const int CollectorFailed = 6;

    /// <summary>Unhandled error.</summary>
    public const int Crashed = 7;
}

/// <summary>
/// Runs inside the elevated helper: creates the secured pipe, accepts exactly the parent process, streams frames,
/// status and log records, and exits when the parent exits, the pipe breaks or the client asks for shutdown.
/// </summary>
public sealed class CollectorPipeHost : ITelemetrySink
{
    private readonly CollectorHostOptions _options;
    private readonly ILogger _logger;
    private readonly Channel<(MessageType Type, byte[] Payload)> _outbox = Channel.CreateBounded<(MessageType, byte[])>(
        new BoundedChannelOptions(4096) { FullMode = BoundedChannelFullMode.DropOldest, SingleReader = true });

    /// <summary>Creates a host.</summary>
    public CollectorPipeHost(CollectorHostOptions options, ILogger logger)
    {
        _options = options;
        _logger = logger;
    }

    /// <summary>Messages dropped because the client did not read fast enough.</summary>
    public long DroppedMessages { get; private set; }

    /// <summary>Forwards a log record to the client (best effort).</summary>
    public void Forward(LogLevel level, string message) =>
        Enqueue(MessageType.Log, TelemetryProtocol.EncodeLog(new LogMessage((int)level, message)));

    void ITelemetrySink.OnFrame(TelemetryFrame frame) => Enqueue(MessageType.Frame, TelemetryProtocol.EncodeFrame(frame));

    void ITelemetrySink.OnStatus(CollectorStatus status) => Enqueue(MessageType.Status, TelemetryProtocol.EncodeStatus(status));

    /// <summary>Runs until the session ends; returns an exit code.</summary>
    public async Task<int> RunAsync(NetworkCollectorOptions collectorOptions, CancellationToken cancellationToken)
    {
        Process parent;
        try
        {
            parent = Process.GetProcessById(_options.ParentPid);
        }
        catch (ArgumentException)
        {
            return CollectorExitCodes.ParentNotFound;
        }

        using var parentProcess = parent;
        using var lifetime = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        _ = parentProcess.WaitForExitAsync(lifetime.Token).ContinueWith(_ => lifetime.Cancel(), TaskScheduler.Default);

        var security = PipeIdentity.CreateSecurity(new SecurityIdentifier(_options.ClientUserSid));
        await using var pipe = NamedPipeServerStreamAcl.Create(
            _options.PipeName,
            PipeDirection.InOut,
            maxNumberOfServerInstances: 1,
            PipeTransmissionMode.Byte,
            PipeOptions.Asynchronous | PipeOptions.FirstPipeInstance,
            inBufferSize: 64 * 1024,
            outBufferSize: 1024 * 1024,
            security);

        using (var connectTimeout = CancellationTokenSource.CreateLinkedTokenSource(lifetime.Token))
        {
            connectTimeout.CancelAfter(TimeSpan.FromSeconds(30));
            try
            {
                await pipe.WaitForConnectionAsync(connectTimeout.Token).ConfigureAwait(false);
            }
            catch (OperationCanceledException)
            {
                return CollectorExitCodes.ConnectTimeout;
            }
        }

        int? clientPid = PipeIdentity.GetClientProcessId(pipe.SafePipeHandle);
        if (clientPid != _options.ParentPid)
        {
            _logger.LogWarning("Rejected pipe client PID {Pid} (expected {Parent}).", clientPid, _options.ParentPid);
            return CollectorExitCodes.UnexpectedClient;
        }

        var collector = new NetworkCollector(collectorOptions, this, _logger);
        await TelemetryProtocol.WriteAsync(
            pipe,
            MessageType.Hello,
            TelemetryProtocol.EncodeHello(new HelloMessage(TelemetryProtocol.Version, Environment.ProcessId, Stopwatch.Frequency, collector.Timeline.BucketTicks, collectorOptions.SessionName)),
            lifetime.Token).ConfigureAwait(false);

        try
        {
            await collector.StartAsync(lifetime.Token).ConfigureAwait(false);
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            // The failure status was queued by the collector; deliver it before exiting.
            _outbox.Writer.TryComplete();
            await DrainAsync(pipe, CancellationToken.None).ConfigureAwait(false);
            _logger.LogError(ex, "Collector failed to start.");
            return CollectorExitCodes.CollectorFailed;
        }

        var writer = WriteLoopAsync(pipe, lifetime.Token);
        var reader = ReadLoopAsync(pipe, lifetime);
        await Task.WhenAny(writer, reader, Task.Delay(Timeout.Infinite, lifetime.Token).ContinueWith(_ => { }, TaskScheduler.Default)).ConfigureAwait(false);
        lifetime.Cancel();
        await collector.DisposeAsync().ConfigureAwait(false);
        return CollectorExitCodes.Success;
    }

    private void Enqueue(MessageType type, byte[] payload)
    {
        if (!_outbox.Writer.TryWrite((type, payload)))
        {
            DroppedMessages++;
        }
    }

    private async Task WriteLoopAsync(Stream pipe, CancellationToken cancellationToken)
    {
        try
        {
            await foreach (var (type, payload) in _outbox.Reader.ReadAllAsync(cancellationToken).ConfigureAwait(false))
            {
                await TelemetryProtocol.WriteAsync(pipe, type, payload, cancellationToken).ConfigureAwait(false);
            }
        }
        catch (Exception ex) when (ex is IOException or OperationCanceledException or ObjectDisposedException)
        {
            // Client went away.
        }
    }

    private async Task DrainAsync(Stream pipe, CancellationToken cancellationToken)
    {
        try
        {
            while (_outbox.Reader.TryRead(out var message))
            {
                await TelemetryProtocol.WriteAsync(pipe, message.Type, message.Payload, cancellationToken).ConfigureAwait(false);
            }
        }
        catch (IOException)
        {
            // Client went away.
        }
    }

    private static async Task ReadLoopAsync(Stream pipe, CancellationTokenSource lifetime)
    {
        try
        {
            while (!lifetime.IsCancellationRequested)
            {
                var message = await TelemetryProtocol.ReadAsync(pipe, lifetime.Token).ConfigureAwait(false);
                if (message is null || message.Value.Type == MessageType.Shutdown)
                {
                    break;
                }
            }
        }
        catch (Exception ex) when (ex is IOException or OperationCanceledException or InvalidDataException or ObjectDisposedException)
        {
            // Treat any protocol violation as disconnect.
        }

        lifetime.Cancel();
    }
}
